// A brief is not a condition that opens and recovers, so it carries no
// alert_key and no state. Branch on the event type first: this shares the ops
// Discord destination with crowdrelay.ops.status_changed, not its shape.
const e = $json;
if (!e || e.type !== 'crowdrelay.ops.operator_brief' || e.version !== 1) return [];
const d = e.data ?? {};
if (!d.headline || !d.summary) throw new Error('Invalid operator brief');
const s = d.snapshot ?? {};

// CrowdRelay already decided there was something worth saying and sends at
// most one a day. Never suppress, batch or re-send here: a delivery path with
// its own quiet hours reproduces the silence the brief exists to break.
const LABELS = {
  approval_stale: 'Decyzja czeka za d\u0142ugo',
  disabled_with_work_waiting: 'Agent nie dzia\u0142a, a praca czeka',
  work_parked: 'Praca zaparkowana \u2014 brak wykonawcy',
  awaiting_approval: 'Decyzje czekaj\u0105 na Ciebie',
  failing: 'Akcje si\u0119 nie powiod\u0142y',
  blind: 'Agent nie widzi cz\u0119\u015bci platform',
  worked: 'Agent pracowa\u0142'
};
const label = LABELS[d.headline] ?? String(d.headline);

// Facts only. The brief reports; the read models and the operator decide.
const lines = [
  `**VIRYA \u2014 ${label}**`,
  '',
  String(d.summary),
  '',
  `Wykonane (24h): ${s.actions_executed_24h ?? 0}`,
  `Nieudane (24h): ${s.actions_failed_24h ?? 0}`,
  `Czeka na akceptacj\u0119: ${s.actions_awaiting_approval ?? 0}`,
  `Zaparkowane (brak wykonawcy): ${s.actions_parked ?? 0}`,
  `Platformy niewidoczne: ${s.blind_platforms ?? 0}`,
  `Agent: ${s.agent_enabled ? 'w\u0142\u0105czony' : 'wy\u0142\u0105czony'}${s.dry_run ? ', dry run' : ''}`
];
if ($env.VIRYA_STAFF_TODAY_URL) lines.push('', `Kolejka: ${$env.VIRYA_STAFF_TODAY_URL}`);

return [{ json: {
  event_id: e.id,
  headline: String(d.headline),
  observed_at: d.observed_at ?? null,
  content: lines.join('\n').slice(0, 1900)
}}];

// The outbox is at-least-once, so the same brief can arrive twice. CrowdRelay
// already guarantees one a day; this only stops a redelivery becoming a second
// message. The marker is the event id, invisible in the rendered text.
const brief = $('Validate and build the brief').first().json;
const marker = `\u200b[brief:${brief.event_id}]`;
const recent = Array.isArray($json) ? $json : ($json.body ?? []);
const already = recent.some(m => String(m?.content || '').includes(marker));
// Pre-serialised: an n8n expression cannot carry a nested object
// literal, because its parser stops at the first `}}`.
const discordBody = JSON.stringify({
  content: brief.content + '\n' + marker,
  allowed_mentions: { parse: [] }
});
return [{ json: { ...brief, marker, already, discordBody } }];

